mapper.select:
SELECT pr.payroll_period, cc.code_name AS payroll_type, pr.payroll_name, pr.payroll_date, pr.payroll_period_code, COUNT(*) AS peopleNumber, SUM(upm.total_payment) AS totalPayment -- 지급총액 FROM tb_payroll pr JOIN tb_cm_code cc ON pr.payroll_type = cc.code LEFT JOIN tb_user_pay_management upm ON upm.payroll_code = pr.payroll_code WHERE 1=1 AND pr.company_code = #{companyCode}
AND pr.payroll_type = #{payrollType}
AND pr.payroll_name like '%' || #{payrollName} || '%'
AND pr.payroll_date >= TO_DATE(#{paymentStartDate} , 'YYYY-MM-DD')
AND pr.payroll_date <= TO_DATE(#{paymentEndDate} , 'YYYY-MM-DD')
GROUP BY pr.payroll_period, cc.code_name, pr.payroll_name, pr.payroll_date, pr.payroll_period_code ORDER BY payroll_period desc

{call sp_calculate_payroll(
    #{payrollPeriodCode, mode=IN, jdbcType=VARCHAR},
    #{key, jdbcType=CURSOR, mode=OUT, javaType=java.sql.ResultSet, resultMap=payrollResultMap}
)}

SELECT COUNT(*)
FROM   tb_user_pay_management
WHERE  payroll_code = #{payrollCode}
